window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-75959d56696099e2"]={"versions": [{"id": "FIG-75959d56696099e2", "releases": ["R4.0.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> Speicherabbildungs- und Adress-Mapping-Diagramm (Memory Layout).</li>\n<li><strong>Technischer Zweck & Einordnung:</strong> Visualisierung der Adressraumtransformation im Modul <em>EEPROM Abstraction</em> (<code>Ea</code>, AUTOSAR Classic BSW, Memory Hardware Abstraction Layer).</li>\n<li><strong>Funktionale Einordnung:</strong></li>\n<li>Vermittelt zwischen der standardisierten, virtuellen Blockadressierung der oberen Schichten (<em>NVRAM Manager</em> / <code>NvM</code> via <em>Memory Abstraction Interface</em> / <code>MemIf</code>) und dem linearen, seitenorientierten Adressraum des zugrundeliegenden <em>EEPROM Drivers</em> (<code>Eep</code>).</li>\n<li>Entkoppelt den 32-Bit-Zugriff (<code>16-Bit Block Number</code> + <code>16-Bit Block Offset</code>) von der physischen Speicherorganisation und bildet variable Blockgrößen auf feste Page-Einheiten (<code>EA_VIRTUAL_PAGE_SIZE</code>) ab.</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Virtueller Adressraum (Upper Layer Sicht / NvM):</strong></li>\n<li><strong>16-Bit Block Number:</strong> Logische Adresskomponente zur Selektion des Datenblocks (theoretischer Wertebereich: $1 \\dots 65535$).</li>\n<li><strong>16-Bit Block Offset:</strong> Byte-Offset innerhalb eines logischen Blocks; limitiert die maximale Nutzdatenlänge eines Blocks auf $64\\,\\text{KiB}$ ($2^{16}\\,\\text{Bytes}$).</li>\n<li><strong>Virtuelle Blöcke (Sparse Mapping):</strong> Jeder logische Block spannt im virtuellen Adressraum bis zu $64\\,\\text{KiB}$ auf; ungenutzter Raum bleibt logisch allokiert, wird jedoch nicht physisch belegt.</li>\n<li><strong>Physischer Adressraum (Lower Layer Sicht / Eep):</strong></li>\n<li><strong>Page-Alignment (<code>EA_VIRTUAL_PAGE_SIZE</code>):</strong> Konfigurierte Paginierungsgröße (im Diagramm: $8\\,\\text{Bytes}$).</li>\n<li><strong>Block-Allokation & Page-Bedarf:</strong></li>\n<li>$\\text{Block }\\#1$: $32\\,\\text{Bytes} \\rightarrow 4\\,\\text{Pages}$ ($4 \\times 8\\,\\text{Bytes} = 32\\,\\text{Bytes}$), kein Verschnitt (<em>0 Bytes internal residue</em>).</li>\n<li>$\\text{Block }\\#5$: $100\\,\\text{Bytes} \\rightarrow 13\\,\\text{Pages}$ ($13 \\times 8\\,\\text{Bytes} = 104\\,\\text{Bytes}$), Verschnitt: $4\\,\\text{Bytes}$ (<em>internal residue</em>).</li>\n<li>$\\text{Block }\\#17$: $38\\,\\text{Bytes} \\rightarrow 5\\,\\text{Pages}$ ($5 \\times 8\\,\\text{Bytes} = 40\\,\\text{Bytes}$), Verschnitt: $2\\,\\text{Bytes}$ (<em>internal residue</em>).</li>\n<li><strong>Mathematische & relationale Bindungen:</strong></li>\n<li><strong>Page-Berechnung:</strong> $\\text{Pages}(B) = \\lceil \\text{BlockSize}(B) / \\text{EA\\_VIRTUAL\\_PAGE\\_SIZE} \\rceil$</li>\n<li><strong>Blocknummern-Fortschaltung:</strong></li>\n</ul>\n<p class=\"fig-p\">$$\\text{BlockID}_{n+1} = \\text{BlockID}_n + \\text{Pages}(B_n)$$</p>\n<p class=\"fig-p\">Daraus resultiert die Sperrung nachfolgender Blocknummern (z. B. blockiert Block $\\#1$ die IDs $2, 3, 4$; Block $\\#5$ blockiert IDs $6 \\dots 16$).</p>\n<ul class=\"fig-list\">\n<li><strong>Internal Residue (Verschnitt):</strong> $\\text{Residue}(B) = (\\text{Pages}(B) \\times \\text{EA\\_VIRTUAL\\_PAGE\\_SIZE}) - \\text{BlockSize}(B)$</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf (Adressierungslogik)</h4>\n<p class=\"fig-p\">Das Diagramm definiert das statische Allokationsmodell, welches die Laufzeit-Adressberechnung deterministisch steuert:</p>\n<ol class=\"fig-list\">\n<li><strong>API-Aufruf:</strong> <code>NvM</code> ruft über <code>MemIf</code> die Schnittstelle <code>Ea_Read</code>, <code>Ea_Write</code> oder <code>Ea_EraseImmediateBlock</code> mit Parametern <code>BlockNumber</code>, <code>BlockOffset</code> und <code>Length</code> auf.</li>\n<li><strong>Adressauflösung:</strong> Das Modul <code>Ea</code> berechnet die physische Basisadresse im EEPROM direkt ohne dynamische Allocation-Tables oder Wear-Leveling (im Gegensatz zu <code>Fee</code>):</li>\n</ol>\n<p class=\"fig-p\">$$\\text{Eep\\_Address} = \\text{Ea\\_BaseAddress} + ((\\text{BlockNumber} - 1) \\times \\text{EA\\_VIRTUAL\\_PAGE\\_SIZE}) + \\text{BlockOffset}$$</p>\n<ol class=\"fig-list\">\n<li><strong>Treiber-Delegation:</strong> <code>Ea</code> setzt die Lese-/Schreibanforderung in synchrone/asynchrone Aufrufe an den Treiber ab (<code>Eep_Read</code>, <code>Eep_Write</code>).</li>\n<li><strong>Fehlerbehandlung:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Ist $(\\text{BlockOffset} + \\text{Length}) > \\text{BlockSize}$, meldet <code>Ea</code> den Fehler <code>EA_E_INVALID_BLOCK_LEN</code> an das <em>Default Error Tracer</em> (<code>Det</code>).</li>\n<li>Ist die <code>BlockNumber</code> ungültig oder nicht konfiguriert, erfolgt <code>EA_E_INVALID_BLOCK_NO</code>.</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Konfigurationsverpflichtung (<code>Ea.bmd</code> / BSW-Tooling):</strong></li>\n<li><code>EaVirtualPageSize</code>: Muss zwingend ein ganzzahliges Vielfaches der hardwarebedingten <code>EepWriteUnitSize</code> / <code>Eep_PageSize</code> des EEPROMs sein.</li>\n<li><strong>Nicht-kontinuierliche Blocknummern:</strong> Konfiguratoren/Integratoren dürfen <code>EaBlockNumber</code> <strong>nicht</strong> fortlaufend inkrementieren ($1, 2, 3 \\dots$). Jede Blocknummer reserviert $N$ virtuelle Page-Indizes. Eine fälschliche Vergabe von Block $\\#2$ bei einem $32$-Byte-Block $\\#1$ führt zu Adressraum-Kollisionen und Datenkorruption.</li>\n<li><strong>Speicherökonomie & Padding:</strong></li>\n<li>Jedes Datenobjekt im NvM sollte idealerweise auf ein Vielfaches von <code>EA_VIRTUAL_PAGE_SIZE</code> aligned werden, um ungenutzten Speicherverschnitt (<em>internal residue</em>) zu eliminieren.</li>\n<li>Da die ungenutzten Bytes einer End-Page für Folgeblöcke unzugänglich sind, verringern unpassende Blockgrößen die Netto-Kapazität des physischen Speichers signifikant.</li>\n<li><strong>Architekturelle Grenzen:</strong></li>\n<li>Adressbereich pro Block fest auf maximal $65.535\\,\\text{Bytes}$ begrenzt.</li>\n<li>Keine implizite Redundanzverwaltung oder Blockverschiebung; defekte Speicherzellen führen ohne übergeordnete NvM-Redundanzmechanismen (<em>Redundant Blocks</em>) zum Datenverlust.</li>\n</ul>"}, {"id": "FIG-38c6593ead6e4669", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> Speicherabbildungs- und Adress-Mapping-Diagramm (Memory Layout).</li>\n<li><strong>Technischer Zweck & Einordnung:</strong> Visualisierung der Adressraumtransformation im Modul <em>EEPROM Abstraction</em> (<code>Ea</code>, AUTOSAR Classic BSW, Memory Hardware Abstraction Layer).</li>\n<li><strong>Funktionale Einordnung:</strong></li>\n<li>Vermittelt zwischen der standardisierten, virtuellen Blockadressierung der oberen Schichten (<em>NVRAM Manager</em> / <code>NvM</code> via <em>Memory Abstraction Interface</em> / <code>MemIf</code>) und dem linearen, seitenorientierten Adressraum des zugrundeliegenden <em>EEPROM Drivers</em> (<code>Eep</code>).</li>\n<li>Entkoppelt den 32-Bit-Zugriff (<code>16-Bit Block Number</code> + <code>16-Bit Block Offset</code>) von der physischen Speicherorganisation und bildet variable Blockgrößen auf feste Page-Einheiten (<code>EA_VIRTUAL_PAGE_SIZE</code>) ab.</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Virtueller Adressraum (Upper Layer Sicht / NvM):</strong></li>\n<li><strong>16-Bit Block Number:</strong> Logische Adresskomponente zur Selektion des Datenblocks (theoretischer Wertebereich: $1 \\dots 65535$).</li>\n<li><strong>16-Bit Block Offset:</strong> Byte-Offset innerhalb eines logischen Blocks; limitiert die maximale Nutzdatenlänge eines Blocks auf $64\\,\\text{KiB}$ ($2^{16}\\,\\text{Bytes}$).</li>\n<li><strong>Virtuelle Blöcke (Sparse Mapping):</strong> Jeder logische Block spannt im virtuellen Adressraum bis zu $64\\,\\text{KiB}$ auf; ungenutzter Raum bleibt logisch allokiert, wird jedoch nicht physisch belegt.</li>\n<li><strong>Physischer Adressraum (Lower Layer Sicht / Eep):</strong></li>\n<li><strong>Page-Alignment (<code>EA_VIRTUAL_PAGE_SIZE</code>):</strong> Konfigurierte Paginierungsgröße (im Diagramm: $8\\,\\text{Bytes}$).</li>\n<li><strong>Block-Allokation & Page-Bedarf:</strong></li>\n<li>$\\text{Block }\\#1$: $32\\,\\text{Bytes} \\rightarrow 4\\,\\text{Pages}$ ($4 \\times 8\\,\\text{Bytes} = 32\\,\\text{Bytes}$), kein Verschnitt (<em>0 Bytes internal residue</em>).</li>\n<li>$\\text{Block }\\#5$: $100\\,\\text{Bytes} \\rightarrow 13\\,\\text{Pages}$ ($13 \\times 8\\,\\text{Bytes} = 104\\,\\text{Bytes}$), Verschnitt: $4\\,\\text{Bytes}$ (<em>internal residue</em>).</li>\n<li>$\\text{Block }\\#17$: $38\\,\\text{Bytes} \\rightarrow 5\\,\\text{Pages}$ ($5 \\times 8\\,\\text{Bytes} = 40\\,\\text{Bytes}$), Verschnitt: $2\\,\\text{Bytes}$ (<em>internal residue</em>).</li>\n<li><strong>Mathematische & relationale Bindungen:</strong></li>\n<li><strong>Page-Berechnung:</strong> $\\text{Pages}(B) = \\lceil \\text{BlockSize}(B) / \\text{EA\\_VIRTUAL\\_PAGE\\_SIZE} \\rceil$</li>\n<li><strong>Blocknummern-Fortschaltung:</strong></li>\n</ul>\n<p class=\"fig-p\">$$\\text{BlockID}_{n+1} = \\text{BlockID}_n + \\text{Pages}(B_n)$$</p>\n<p class=\"fig-p\">Daraus resultiert die Sperrung nachfolgender Blocknummern (z. B. blockiert Block $\\#1$ die IDs $2, 3, 4$; Block $\\#5$ blockiert IDs $6 \\dots 16$).</p>\n<ul class=\"fig-list\">\n<li><strong>Internal Residue (Verschnitt):</strong> $\\text{Residue}(B) = (\\text{Pages}(B) \\times \\text{EA\\_VIRTUAL\\_PAGE\\_SIZE}) - \\text{BlockSize}(B)$</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Diagramm definiert das statische Allokationsmodell, welches die Laufzeit-Adressberechnung deterministisch steuert:</p>\n<ol class=\"fig-list\">\n<li><strong>API-Aufruf:</strong> <code>NvM</code> ruft über <code>MemIf</code> die Schnittstelle <code>Ea_Read</code>, <code>Ea_Write</code> oder <code>Ea_EraseImmediateBlock</code> mit Parametern <code>BlockNumber</code>, <code>BlockOffset</code> und <code>Length</code> auf.</li>\n<li><strong>Adressauflösung:</strong> Das Modul <code>Ea</code> berechnet die physische Basisadresse im EEPROM direkt ohne dynamische Allocation-Tables oder Wear-Leveling (im Gegensatz zu <code>Fee</code>):</li>\n</ol>\n<p class=\"fig-p\">$$\\text{Eep\\_Address} = \\text{Ea\\_BaseAddress} + ((\\text{BlockNumber} - 1) \\times \\text{EA\\_VIRTUAL\\_PAGE\\_SIZE}) + \\text{BlockOffset}$$</p>\n<ol class=\"fig-list\">\n<li><strong>Treiber-Delegation:</strong> <code>Ea</code> setzt die Lese-/Schreibanforderung in synchrone/asynchrone Aufrufe an den Treiber ab (<code>Eep_Read</code>, <code>Eep_Write</code>).</li>\n<li><strong>Fehlerbehandlung:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Ist $(\\text{BlockOffset} + \\text{Length}) > \\text{BlockSize}$, meldet <code>Ea</code> den Fehler <code>EA_E_INVALID_BLOCK_LEN</code> an das <em>Default Error Tracer</em> (<code>Det</code>).</li>\n<li>Ist die <code>BlockNumber</code> ungültig oder nicht konfiguriert, erfolgt <code>EA_E_INVALID_BLOCK_NO</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Konfigurationsverpflichtung (<code>Ea.bmd</code> / BSW-Tooling):</strong></li>\n<li><code>EaVirtualPageSize</code>: Muss zwingend ein ganzzahliges Vielfaches der hardwarebedingten <code>EepWriteUnitSize</code> / <code>Eep_PageSize</code> des EEPROMs sein.</li>\n<li><strong>Nicht-kontinuierliche Blocknummern:</strong> Konfiguratoren/Integratoren dürfen <code>EaBlockNumber</code> <strong>nicht</strong> fortlaufend inkrementieren ($1, 2, 3 \\dots$). Jede Blocknummer reserviert $N$ virtuelle Page-Indizes. Eine fälschliche Vergabe von Block $\\#2$ bei einem $32$-Byte-Block $\\#1$ führt zu Adressraum-Kollisionen und Datenkorruption.</li>\n<li><strong>Speicherökonomie & Padding:</strong></li>\n<li>Jedes Datenobjekt im NvM sollte idealerweise auf ein Vielfaches von <code>EA_VIRTUAL_PAGE_SIZE</code> aligned werden, um ungenutzten Speicherverschnitt (<em>internal residue</em>) zu eliminieren.</li>\n<li>Da die ungenutzten Bytes einer End-Page für Folgeblöcke unzugänglich sind, verringern unpassende Blockgrößen die Netto-Kapazität des physischen Speichers signifikant.</li>\n<li><strong>Architekturelle Grenzen:</strong></li>\n<li>Adressbereich pro Block fest auf maximal $65.535\\,\\text{Bytes}$ begrenzt.</li>\n<li>Keine implizite Redundanzverwaltung oder Blockverschiebung; defekte Speicherzellen führen ohne übergeordnete NvM-Redundanzmechanismen (<em>Redundant Blocks</em>) zum Datenverlust.</li>\n</ul>"}, {"id": "FIG-6f36a54eb3458c11", "releases": ["R4.2.2", "R4.3.1", "R18-10_R4.4.0_R1.5.0"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> Speicherabbildungs- und Adress-Mapping-Diagramm (Memory Layout).</li>\n<li><strong>Technischer Zweck & Einordnung:</strong> Visualisierung der Adressraumtransformation im Modul <em>EEPROM Abstraction</em> (<code>Ea</code>, AUTOSAR Classic BSW, Memory Hardware Abstraction Layer).</li>\n<li><strong>Funktionale Einordnung:</strong></li>\n<li>Vermittelt zwischen der standardisierten, virtuellen Blockadressierung der oberen Schichten (<em>NVRAM Manager</em> / <code>NvM</code> via <em>Memory Abstraction Interface</em> / <code>MemIf</code>) und dem linearen, seitenorientierten Adressraum des zugrundeliegenden <em>EEPROM Drivers</em> (<code>Eep</code>).</li>\n<li>Entkoppelt den 32-Bit-Zugriff (<code>16-Bit Block Number</code> + <code>16-Bit Block Offset</code>) von der physischen Speicherorganisation und bildet variable Blockgrößen auf feste Page-Einheiten (<code>EA_VIRTUAL_PAGE_SIZE</code>) ab.</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Virtueller Adressraum (Upper Layer Sicht / NvM):</strong></li>\n<li><strong>16-Bit Block Number:</strong> Logische Adresskomponente zur Selektion des Datenblocks (theoretischer Wertebereich: $1 \\dots 65535$).</li>\n<li><strong>16-Bit Block Offset:</strong> Byte-Offset innerhalb eines logischen Blocks; limitiert die maximale Nutzdatenlänge eines Blocks auf $64\\,\\text{KiB}$ ($2^{16}\\,\\text{Bytes}$).</li>\n<li><strong>Virtuelle Blöcke (Sparse Mapping):</strong> Jeder logische Block spannt im virtuellen Adressraum bis zu $64\\,\\text{KiB}$ auf; ungenutzter Raum bleibt logisch allokiert, wird jedoch nicht physisch belegt.</li>\n<li><strong>Physischer Adressraum (Lower Layer Sicht / Eep):</strong></li>\n<li><strong>Page-Alignment (<code>EA_VIRTUAL_PAGE_SIZE</code>):</strong> Konfigurierte Paginierungsgröße (im Diagramm: $8\\,\\text{Bytes}$).</li>\n<li><strong>Block-Allokation & Page-Bedarf:</strong></li>\n<li>$\\text{Block }\\#1$: $32\\,\\text{Bytes} \\rightarrow 4\\,\\text{Pages}$ ($4 \\times 8\\,\\text{Bytes} = 32\\,\\text{Bytes}$), kein Verschnitt (<em>0 Bytes internal residue</em>).</li>\n<li>$\\text{Block }\\#5$: $100\\,\\text{Bytes} \\rightarrow 13\\,\\text{Pages}$ ($13 \\times 8\\,\\text{Bytes} = 104\\,\\text{Bytes}$), Verschnitt: $4\\,\\text{Bytes}$ (<em>internal residue</em>).</li>\n<li>$\\text{Block }\\#17$: $38\\,\\text{Bytes} \\rightarrow 5\\,\\text{Pages}$ ($5 \\times 8\\,\\text{Bytes} = 40\\,\\text{Bytes}$), Verschnitt: $2\\,\\text{Bytes}$ (<em>internal residue</em>).</li>\n<li><strong>Mathematische & relationale Bindungen:</strong></li>\n<li><strong>Page-Berechnung:</strong> $\\text{Pages}(B) = \\lceil \\text{BlockSize}(B) / \\text{EA\\_VIRTUAL\\_PAGE\\_SIZE} \\rceil$</li>\n<li><strong>Blocknummern-Fortschaltung:</strong></li>\n</ul>\n<p class=\"fig-p\">$$\\text{BlockID}_{n+1} = \\text{BlockID}_n + \\text{Pages}(B_n)$$</p>\n<p class=\"fig-p\">Daraus resultiert die Sperrung nachfolgender Blocknummern (z. B. blockiert Block $\\#1$ die IDs $2, 3, 4$; Block $\\#5$ blockiert IDs $6 \\dots 16$).</p>\n<ul class=\"fig-list\">\n<li><strong>Internal Residue (Verschnitt):</strong> $\\text{Residue}(B) = (\\text{Pages}(B) \\times \\text{EA\\_VIRTUAL\\_PAGE\\_SIZE}) - \\text{BlockSize}(B)$</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Diagramm definiert das statische Allokationsmodell, welches die Laufzeit-Adressberechnung deterministisch steuert:</p>\n<ol class=\"fig-list\">\n<li><strong>API-Aufruf:</strong> <code>NvM</code> ruft über <code>MemIf</code> die Schnittstelle <code>Ea_Read</code>, <code>Ea_Write</code> oder <code>Ea_EraseImmediateBlock</code> mit Parametern <code>BlockNumber</code>, <code>BlockOffset</code> und <code>Length</code> auf.</li>\n<li><strong>Adressauflösung:</strong> Das Modul <code>Ea</code> berechnet die physische Basisadresse im EEPROM direkt ohne dynamische Allocation-Tables oder Wear-Leveling (im Gegensatz zu <code>Fee</code>):</li>\n</ol>\n<p class=\"fig-p\">$$\\text{Eep\\_Address} = \\text{Ea\\_BaseAddress} + ((\\text{BlockNumber} - 1) \\times \\text{EA\\_VIRTUAL\\_PAGE\\_SIZE}) + \\text{BlockOffset}$$</p>\n<ol class=\"fig-list\">\n<li><strong>Treiber-Delegation:</strong> <code>Ea</code> setzt die Lese-/Schreibanforderung in synchrone/asynchrone Aufrufe an den Treiber ab (<code>Eep_Read</code>, <code>Eep_Write</code>).</li>\n<li><strong>Fehlerbehandlung:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Ist $(\\text{BlockOffset} + \\text{Length}) > \\text{BlockSize}$, meldet <code>Ea</code> den Fehler <code>EA_E_INVALID_BLOCK_LEN</code> an das <em>Default Error Tracer</em> (<code>Det</code>).</li>\n<li>Ist die <code>BlockNumber</code> ungültig oder nicht konfiguriert, erfolgt <code>EA_E_INVALID_BLOCK_NO</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Konfigurationsverpflichtung (<code>Ea.bmd</code> / BSW-Tooling):</strong></li>\n<li><code>EaVirtualPageSize</code>: Muss zwingend ein ganzzahliges Vielfaches der hardwarebedingten <code>EepWriteUnitSize</code> / <code>Eep_PageSize</code> des EEPROMs sein.</li>\n<li><strong>Nicht-kontinuierliche Blocknummern:</strong> Konfiguratoren/Integratoren dürfen <code>EaBlockNumber</code> <strong>nicht</strong> fortlaufend inkrementieren ($1, 2, 3 \\dots$). Jede Blocknummer reserviert $N$ virtuelle Page-Indizes. Eine fälschliche Vergabe von Block $\\#2$ bei einem $32$-Byte-Block $\\#1$ führt zu Adressraum-Kollisionen und Datenkorruption.</li>\n<li><strong>Speicherökonomie & Padding:</strong></li>\n<li>Jedes Datenobjekt im NvM sollte idealerweise auf ein Vielfaches von <code>EA_VIRTUAL_PAGE_SIZE</code> aligned werden, um ungenutzten Speicherverschnitt (<em>internal residue</em>) zu eliminieren.</li>\n<li>Da die ungenutzten Bytes einer End-Page für Folgeblöcke unzugänglich sind, verringern unpassende Blockgrößen die Netto-Kapazität des physischen Speichers signifikant.</li>\n<li><strong>Architekturelle Grenzen:</strong></li>\n<li>Adressbereich pro Block fest auf maximal $65.535\\,\\text{Bytes}$ begrenzt.</li>\n<li>Keine implizite Redundanzverwaltung oder Blockverschiebung; defekte Speicherzellen führen ohne übergeordnete NvM-Redundanzmechanismen (<em>Redundant Blocks</em>) zum Datenverlust.</li>\n</ul>"}, {"id": "FIG-145c8b4514ffef45", "releases": ["R19-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> Speicherabbildungs- und Adress-Mapping-Diagramm (Memory Layout).</li>\n<li><strong>Technischer Zweck & Einordnung:</strong> Visualisierung der Adressraumtransformation im Modul <em>EEPROM Abstraction</em> (<code>Ea</code>, AUTOSAR Classic BSW, Memory Hardware Abstraction Layer).</li>\n<li><strong>Funktionale Einordnung:</strong></li>\n<li>Vermittelt zwischen der standardisierten, virtuellen Blockadressierung der oberen Schichten (<em>NVRAM Manager</em> / <code>NvM</code> via <em>Memory Abstraction Interface</em> / <code>MemIf</code>) und dem linearen, seitenorientierten Adressraum des zugrundeliegenden <em>EEPROM Drivers</em> (<code>Eep</code>).</li>\n<li>Entkoppelt den 32-Bit-Zugriff (<code>16-Bit Block Number</code> + <code>16-Bit Block Offset</code>) von der physischen Speicherorganisation und bildet variable Blockgrößen auf feste Page-Einheiten (<code>EA_VIRTUAL_PAGE_SIZE</code>) ab.</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Virtueller Adressraum (Upper Layer Sicht / NvM):</strong></li>\n<li><strong>16-Bit Block Number:</strong> Logische Adresskomponente zur Selektion des Datenblocks (theoretischer Wertebereich: $1 \\dots 65535$).</li>\n<li><strong>16-Bit Block Offset:</strong> Byte-Offset innerhalb eines logischen Blocks; limitiert die maximale Nutzdatenlänge eines Blocks auf $64\\,\\text{KiB}$ ($2^{16}\\,\\text{Bytes}$).</li>\n<li><strong>Virtuelle Blöcke (Sparse Mapping):</strong> Jeder logische Block spannt im virtuellen Adressraum bis zu $64\\,\\text{KiB}$ auf; ungenutzter Raum bleibt logisch allokiert, wird jedoch nicht physisch belegt.</li>\n<li><strong>Physischer Adressraum (Lower Layer Sicht / Eep):</strong></li>\n<li><strong>Page-Alignment (<code>EA_VIRTUAL_PAGE_SIZE</code>):</strong> Konfigurierte Paginierungsgröße (im Diagramm: $8\\,\\text{Bytes}$).</li>\n<li><strong>Block-Allokation & Page-Bedarf:</strong></li>\n<li>$\\text{Block }\\#1$: $32\\,\\text{Bytes} \\rightarrow 4\\,\\text{Pages}$ ($4 \\times 8\\,\\text{Bytes} = 32\\,\\text{Bytes}$), kein Verschnitt (<em>0 Bytes internal residue</em>).</li>\n<li>$\\text{Block }\\#5$: $100\\,\\text{Bytes} \\rightarrow 13\\,\\text{Pages}$ ($13 \\times 8\\,\\text{Bytes} = 104\\,\\text{Bytes}$), Verschnitt: $4\\,\\text{Bytes}$ (<em>internal residue</em>).</li>\n<li>$\\text{Block }\\#17$: $38\\,\\text{Bytes} \\rightarrow 5\\,\\text{Pages}$ ($5 \\times 8\\,\\text{Bytes} = 40\\,\\text{Bytes}$), Verschnitt: $2\\,\\text{Bytes}$ (<em>internal residue</em>).</li>\n<li><strong>Mathematische & relationale Bindungen:</strong></li>\n<li><strong>Page-Berechnung:</strong> $\\text{Pages}(B) = \\lceil \\text{BlockSize}(B) / \\text{EA\\_VIRTUAL\\_PAGE\\_SIZE} \\rceil$</li>\n<li><strong>Blocknummern-Fortschaltung:</strong></li>\n</ul>\n<p class=\"fig-p\">$$\\text{BlockID}_{n+1} = \\text{BlockID}_n + \\text{Pages}(B_n)$$</p>\n<p class=\"fig-p\">Daraus resultiert die Sperrung nachfolgender Blocknummern (z. B. blockiert Block $\\#1$ die IDs $2, 3, 4$; Block $\\#5$ blockiert IDs $6 \\dots 16$).</p>\n<ul class=\"fig-list\">\n<li><strong>Internal Residue (Verschnitt):</strong> $\\text{Residue}(B) = (\\text{Pages}(B) \\times \\text{EA\\_VIRTUAL\\_PAGE\\_SIZE}) - \\text{BlockSize}(B)$</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Diagramm definiert das statische Allokationsmodell, welches die Laufzeit-Adressberechnung deterministisch steuert:</p>\n<ol class=\"fig-list\">\n<li><strong>API-Aufruf:</strong> <code>NvM</code> ruft über <code>MemIf</code> die Schnittstelle <code>Ea_Read</code>, <code>Ea_Write</code> oder <code>Ea_EraseImmediateBlock</code> mit Parametern <code>BlockNumber</code>, <code>BlockOffset</code> und <code>Length</code> auf.</li>\n<li><strong>Adressauflösung:</strong> Das Modul <code>Ea</code> berechnet die physische Basisadresse im EEPROM direkt ohne dynamische Allocation-Tables oder Wear-Leveling (im Gegensatz zu <code>Fee</code>):</li>\n</ol>\n<p class=\"fig-p\">$$\\text{Eep\\_Address} = \\text{Ea\\_BaseAddress} + ((\\text{BlockNumber} - 1) \\times \\text{EA\\_VIRTUAL\\_PAGE\\_SIZE}) + \\text{BlockOffset}$$</p>\n<ol class=\"fig-list\">\n<li><strong>Treiber-Delegation:</strong> <code>Ea</code> setzt die Lese-/Schreibanforderung in synchrone/asynchrone Aufrufe an den Treiber ab (<code>Eep_Read</code>, <code>Eep_Write</code>).</li>\n<li><strong>Fehlerbehandlung:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Ist $(\\text{BlockOffset} + \\text{Length}) > \\text{BlockSize}$, meldet <code>Ea</code> den Fehler <code>EA_E_INVALID_BLOCK_LEN</code> an das <em>Default Error Tracer</em> (<code>Det</code>).</li>\n<li>Ist die <code>BlockNumber</code> ungültig oder nicht konfiguriert, erfolgt <code>EA_E_INVALID_BLOCK_NO</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Konfigurationsverpflichtung (<code>Ea.bmd</code> / BSW-Tooling):</strong></li>\n<li><code>EaVirtualPageSize</code>: Muss zwingend ein ganzzahliges Vielfaches der hardwarebedingten <code>EepWriteUnitSize</code> / <code>Eep_PageSize</code> des EEPROMs sein.</li>\n<li><strong>Nicht-kontinuierliche Blocknummern:</strong> Konfiguratoren/Integratoren dürfen <code>EaBlockNumber</code> <strong>nicht</strong> fortlaufend inkrementieren ($1, 2, 3 \\dots$). Jede Blocknummer reserviert $N$ virtuelle Page-Indizes. Eine fälschliche Vergabe von Block $\\#2$ bei einem $32$-Byte-Block $\\#1$ führt zu Adressraum-Kollisionen und Datenkorruption.</li>\n<li><strong>Speicherökonomie & Padding:</strong></li>\n<li>Jedes Datenobjekt im NvM sollte idealerweise auf ein Vielfaches von <code>EA_VIRTUAL_PAGE_SIZE</code> aligned werden, um ungenutzten Speicherverschnitt (<em>internal residue</em>) zu eliminieren.</li>\n<li>Da die ungenutzten Bytes einer End-Page für Folgeblöcke unzugänglich sind, verringern unpassende Blockgrößen die Netto-Kapazität des physischen Speichers signifikant.</li>\n<li><strong>Architekturelle Grenzen:</strong></li>\n<li>Adressbereich pro Block fest auf maximal $65.535\\,\\text{Bytes}$ begrenzt.</li>\n<li>Keine implizite Redundanzverwaltung oder Blockverschiebung; defekte Speicherzellen führen ohne übergeordnete NvM-Redundanzmechanismen (<em>Redundant Blocks</em>) zum Datenverlust.</li>\n</ul>"}, {"id": "FIG-ac637fea65c6a128", "releases": ["R20-11", "R21-11", "R22-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> Speicherabbildungs- und Adress-Mapping-Diagramm (Memory Layout).</li>\n<li><strong>Technischer Zweck & Einordnung:</strong> Visualisierung der Adressraumtransformation im Modul <em>EEPROM Abstraction</em> (<code>Ea</code>, AUTOSAR Classic BSW, Memory Hardware Abstraction Layer).</li>\n<li><strong>Funktionale Einordnung:</strong></li>\n<li>Vermittelt zwischen der standardisierten, virtuellen Blockadressierung der oberen Schichten (<em>NVRAM Manager</em> / <code>NvM</code> via <em>Memory Abstraction Interface</em> / <code>MemIf</code>) und dem linearen, seitenorientierten Adressraum des zugrundeliegenden <em>EEPROM Drivers</em> (<code>Eep</code>).</li>\n<li>Entkoppelt den 32-Bit-Zugriff (<code>16-Bit Block Number</code> + <code>16-Bit Block Offset</code>) von der physischen Speicherorganisation und bildet variable Blockgrößen auf feste Page-Einheiten (<code>EA_VIRTUAL_PAGE_SIZE</code>) ab.</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Virtueller Adressraum (Upper Layer Sicht / NvM):</strong></li>\n<li><strong>16-Bit Block Number:</strong> Logische Adresskomponente zur Selektion des Datenblocks (theoretischer Wertebereich: $1 \\dots 65535$).</li>\n<li><strong>16-Bit Block Offset:</strong> Byte-Offset innerhalb eines logischen Blocks; limitiert die maximale Nutzdatenlänge eines Blocks auf $64\\,\\text{KiB}$ ($2^{16}\\,\\text{Bytes}$).</li>\n<li><strong>Virtuelle Blöcke (Sparse Mapping):</strong> Jeder logische Block spannt im virtuellen Adressraum bis zu $64\\,\\text{KiB}$ auf; ungenutzter Raum bleibt logisch allokiert, wird jedoch nicht physisch belegt.</li>\n<li><strong>Physischer Adressraum (Lower Layer Sicht / Eep):</strong></li>\n<li><strong>Page-Alignment (<code>EA_VIRTUAL_PAGE_SIZE</code>):</strong> Konfigurierte Paginierungsgröße (im Diagramm: $8\\,\\text{Bytes}$).</li>\n<li><strong>Block-Allokation & Page-Bedarf:</strong></li>\n<li>$\\text{Block }\\#1$: $32\\,\\text{Bytes} \\rightarrow 4\\,\\text{Pages}$ ($4 \\times 8\\,\\text{Bytes} = 32\\,\\text{Bytes}$), kein Verschnitt (<em>0 Bytes internal residue</em>).</li>\n<li>$\\text{Block }\\#5$: $100\\,\\text{Bytes} \\rightarrow 13\\,\\text{Pages}$ ($13 \\times 8\\,\\text{Bytes} = 104\\,\\text{Bytes}$), Verschnitt: $4\\,\\text{Bytes}$ (<em>internal residue</em>).</li>\n<li>$\\text{Block }\\#17$: $38\\,\\text{Bytes} \\rightarrow 5\\,\\text{Pages}$ ($5 \\times 8\\,\\text{Bytes} = 40\\,\\text{Bytes}$), Verschnitt: $2\\,\\text{Bytes}$ (<em>internal residue</em>).</li>\n<li><strong>Mathematische & relationale Bindungen:</strong></li>\n<li><strong>Page-Berechnung:</strong> $\\text{Pages}(B) = \\lceil \\text{BlockSize}(B) / \\text{EA\\_VIRTUAL\\_PAGE\\_SIZE} \\rceil$</li>\n<li><strong>Blocknummern-Fortschaltung:</strong></li>\n</ul>\n<p class=\"fig-p\">$$\\text{BlockID}_{n+1} = \\text{BlockID}_n + \\text{Pages}(B_n)$$</p>\n<p class=\"fig-p\">Daraus resultiert die Sperrung nachfolgender Blocknummern (z. B. blockiert Block $\\#1$ die IDs $2, 3, 4$; Block $\\#5$ blockiert IDs $6 \\dots 16$).</p>\n<ul class=\"fig-list\">\n<li><strong>Internal Residue (Verschnitt):</strong> $\\text{Residue}(B) = (\\text{Pages}(B) \\times \\text{EA\\_VIRTUAL\\_PAGE\\_SIZE}) - \\text{BlockSize}(B)$</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Diagramm definiert das statische Allokationsmodell, welches die Laufzeit-Adressberechnung deterministisch steuert:</p>\n<ol class=\"fig-list\">\n<li><strong>API-Aufruf:</strong> <code>NvM</code> ruft über <code>MemIf</code> die Schnittstelle <code>Ea_Read</code>, <code>Ea_Write</code> oder <code>Ea_EraseImmediateBlock</code> mit Parametern <code>BlockNumber</code>, <code>BlockOffset</code> und <code>Length</code> auf.</li>\n<li><strong>Adressauflösung:</strong> Das Modul <code>Ea</code> berechnet die physische Basisadresse im EEPROM direkt ohne dynamische Allocation-Tables oder Wear-Leveling (im Gegensatz zu <code>Fee</code>):</li>\n</ol>\n<p class=\"fig-p\">$$\\text{Eep\\_Address} = \\text{Ea\\_BaseAddress} + ((\\text{BlockNumber} - 1) \\times \\text{EA\\_VIRTUAL\\_PAGE\\_SIZE}) + \\text{BlockOffset}$$</p>\n<ol class=\"fig-list\">\n<li><strong>Treiber-Delegation:</strong> <code>Ea</code> setzt die Lese-/Schreibanforderung in synchrone/asynchrone Aufrufe an den Treiber ab (<code>Eep_Read</code>, <code>Eep_Write</code>).</li>\n<li><strong>Fehlerbehandlung:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Ist $(\\text{BlockOffset} + \\text{Length}) > \\text{BlockSize}$, meldet <code>Ea</code> den Fehler <code>EA_E_INVALID_BLOCK_LEN</code> an das <em>Default Error Tracer</em> (<code>Det</code>).</li>\n<li>Ist die <code>BlockNumber</code> ungültig oder nicht konfiguriert, erfolgt <code>EA_E_INVALID_BLOCK_NO</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Konfigurationsverpflichtung (<code>Ea.bmd</code> / BSW-Tooling):</strong></li>\n<li><code>EaVirtualPageSize</code>: Muss zwingend ein ganzzahliges Vielfaches der hardwarebedingten <code>EepWriteUnitSize</code> / <code>Eep_PageSize</code> des EEPROMs sein.</li>\n<li><strong>Nicht-kontinuierliche Blocknummern:</strong> Konfiguratoren/Integratoren dürfen <code>EaBlockNumber</code> <strong>nicht</strong> fortlaufend inkrementieren ($1, 2, 3 \\dots$). Jede Blocknummer reserviert $N$ virtuelle Page-Indizes. Eine fälschliche Vergabe von Block $\\#2$ bei einem $32$-Byte-Block $\\#1$ führt zu Adressraum-Kollisionen und Datenkorruption.</li>\n<li><strong>Speicherökonomie & Padding:</strong></li>\n<li>Jedes Datenobjekt im NvM sollte idealerweise auf ein Vielfaches von <code>EA_VIRTUAL_PAGE_SIZE</code> aligned werden, um ungenutzten Speicherverschnitt (<em>internal residue</em>) zu eliminieren.</li>\n<li>Da die ungenutzten Bytes einer End-Page für Folgeblöcke unzugänglich sind, verringern unpassende Blockgrößen die Netto-Kapazität des physischen Speichers signifikant.</li>\n<li><strong>Architekturelle Grenzen:</strong></li>\n<li>Adressbereich pro Block fest auf maximal $65.535\\,\\text{Bytes}$ begrenzt.</li>\n<li>Keine implizite Redundanzverwaltung oder Blockverschiebung; defekte Speicherzellen führen ohne übergeordnete NvM-Redundanzmechanismen (<em>Redundant Blocks</em>) zum Datenverlust.</li>\n</ul>"}, {"id": "FIG-ec6d8834130d7dfa", "releases": ["R23-11", "R24-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> Speicherabbildungs- und Adress-Mapping-Diagramm (Memory Layout).</li>\n<li><strong>Technischer Zweck & Einordnung:</strong> Visualisierung der Adressraumtransformation im Modul <em>EEPROM Abstraction</em> (<code>Ea</code>, AUTOSAR Classic BSW, Memory Hardware Abstraction Layer).</li>\n<li><strong>Funktionale Einordnung:</strong></li>\n<li>Vermittelt zwischen der standardisierten, virtuellen Blockadressierung der oberen Schichten (<em>NVRAM Manager</em> / <code>NvM</code> via <em>Memory Abstraction Interface</em> / <code>MemIf</code>) und dem linearen, seitenorientierten Adressraum des zugrundeliegenden <em>EEPROM Drivers</em> (<code>Eep</code>).</li>\n<li>Entkoppelt den 32-Bit-Zugriff (<code>16-Bit Block Number</code> + <code>16-Bit Block Offset</code>) von der physischen Speicherorganisation und bildet variable Blockgrößen auf feste Page-Einheiten (<code>EA_VIRTUAL_PAGE_SIZE</code>) ab.</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Virtueller Adressraum (Upper Layer Sicht / NvM):</strong></li>\n<li><strong>16-Bit Block Number:</strong> Logische Adresskomponente zur Selektion des Datenblocks (theoretischer Wertebereich: $1 \\dots 65535$).</li>\n<li><strong>16-Bit Block Offset:</strong> Byte-Offset innerhalb eines logischen Blocks; limitiert die maximale Nutzdatenlänge eines Blocks auf $64\\,\\text{KiB}$ ($2^{16}\\,\\text{Bytes}$).</li>\n<li><strong>Virtuelle Blöcke (Sparse Mapping):</strong> Jeder logische Block spannt im virtuellen Adressraum bis zu $64\\,\\text{KiB}$ auf; ungenutzter Raum bleibt logisch allokiert, wird jedoch nicht physisch belegt.</li>\n<li><strong>Physischer Adressraum (Lower Layer Sicht / Eep):</strong></li>\n<li><strong>Page-Alignment (<code>EA_VIRTUAL_PAGE_SIZE</code>):</strong> Konfigurierte Paginierungsgröße (im Diagramm: $8\\,\\text{Bytes}$).</li>\n<li><strong>Block-Allokation & Page-Bedarf:</strong></li>\n<li>$\\text{Block }\\#1$: $32\\,\\text{Bytes} \\rightarrow 4\\,\\text{Pages}$ ($4 \\times 8\\,\\text{Bytes} = 32\\,\\text{Bytes}$), kein Verschnitt (<em>0 Bytes internal residue</em>).</li>\n<li>$\\text{Block }\\#5$: $100\\,\\text{Bytes} \\rightarrow 13\\,\\text{Pages}$ ($13 \\times 8\\,\\text{Bytes} = 104\\,\\text{Bytes}$), Verschnitt: $4\\,\\text{Bytes}$ (<em>internal residue</em>).</li>\n<li>$\\text{Block }\\#17$: $38\\,\\text{Bytes} \\rightarrow 5\\,\\text{Pages}$ ($5 \\times 8\\,\\text{Bytes} = 40\\,\\text{Bytes}$), Verschnitt: $2\\,\\text{Bytes}$ (<em>internal residue</em>).</li>\n<li><strong>Mathematische & relationale Bindungen:</strong></li>\n<li><strong>Page-Berechnung:</strong> $\\text{Pages}(B) = \\lceil \\text{BlockSize}(B) / \\text{EA\\_VIRTUAL\\_PAGE\\_SIZE} \\rceil$</li>\n<li><strong>Blocknummern-Fortschaltung:</strong></li>\n</ul>\n<p class=\"fig-p\">$$\\text{BlockID}_{n+1} = \\text{BlockID}_n + \\text{Pages}(B_n)$$</p>\n<p class=\"fig-p\">Daraus resultiert die Sperrung nachfolgender Blocknummern (z. B. blockiert Block $\\#1$ die IDs $2, 3, 4$; Block $\\#5$ blockiert IDs $6 \\dots 16$).</p>\n<ul class=\"fig-list\">\n<li><strong>Internal Residue (Verschnitt):</strong> $\\text{Residue}(B) = (\\text{Pages}(B) \\times \\text{EA\\_VIRTUAL\\_PAGE\\_SIZE}) - \\text{BlockSize}(B)$</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Diagramm definiert das statische Allokationsmodell, welches die Laufzeit-Adressberechnung deterministisch steuert:</p>\n<ol class=\"fig-list\">\n<li><strong>API-Aufruf:</strong> <code>NvM</code> ruft über <code>MemIf</code> die Schnittstelle <code>Ea_Read</code>, <code>Ea_Write</code> oder <code>Ea_EraseImmediateBlock</code> mit Parametern <code>BlockNumber</code>, <code>BlockOffset</code> und <code>Length</code> auf.</li>\n<li><strong>Adressauflösung:</strong> Das Modul <code>Ea</code> berechnet die physische Basisadresse im EEPROM direkt ohne dynamische Allocation-Tables oder Wear-Leveling (im Gegensatz zu <code>Fee</code>):</li>\n</ol>\n<p class=\"fig-p\">$$\\text{Eep\\_Address} = \\text{Ea\\_BaseAddress} + ((\\text{BlockNumber} - 1) \\times \\text{EA\\_VIRTUAL\\_PAGE\\_SIZE}) + \\text{BlockOffset}$$</p>\n<ol class=\"fig-list\">\n<li><strong>Treiber-Delegation:</strong> <code>Ea</code> setzt die Lese-/Schreibanforderung in synchrone/asynchrone Aufrufe an den Treiber ab (<code>Eep_Read</code>, <code>Eep_Write</code>).</li>\n<li><strong>Fehlerbehandlung:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Ist $(\\text{BlockOffset} + \\text{Length}) > \\text{BlockSize}$, meldet <code>Ea</code> den Fehler <code>EA_E_INVALID_BLOCK_LEN</code> an das <em>Default Error Tracer</em> (<code>Det</code>).</li>\n<li>Ist die <code>BlockNumber</code> ungültig oder nicht konfiguriert, erfolgt <code>EA_E_INVALID_BLOCK_NO</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Konfigurationsverpflichtung (<code>Ea.bmd</code> / BSW-Tooling):</strong></li>\n<li><code>EaVirtualPageSize</code>: Muss zwingend ein ganzzahliges Vielfaches der hardwarebedingten <code>EepWriteUnitSize</code> / <code>Eep_PageSize</code> des EEPROMs sein.</li>\n<li><strong>Nicht-kontinuierliche Blocknummern:</strong> Konfiguratoren/Integratoren dürfen <code>EaBlockNumber</code> <strong>nicht</strong> fortlaufend inkrementieren ($1, 2, 3 \\dots$). Jede Blocknummer reserviert $N$ virtuelle Page-Indizes. Eine fälschliche Vergabe von Block $\\#2$ bei einem $32$-Byte-Block $\\#1$ führt zu Adressraum-Kollisionen und Datenkorruption.</li>\n<li><strong>Speicherökonomie & Padding:</strong></li>\n<li>Jedes Datenobjekt im NvM sollte idealerweise auf ein Vielfaches von <code>EA_VIRTUAL_PAGE_SIZE</code> aligned werden, um ungenutzten Speicherverschnitt (<em>internal residue</em>) zu eliminieren.</li>\n<li>Da die ungenutzten Bytes einer End-Page für Folgeblöcke unzugänglich sind, verringern unpassende Blockgrößen die Netto-Kapazität des physischen Speichers signifikant.</li>\n<li><strong>Architekturelle Grenzen:</strong></li>\n<li>Adressbereich pro Block fest auf maximal $65.535\\,\\text{Bytes}$ begrenzt.</li>\n<li>Keine implizite Redundanzverwaltung oder Blockverschiebung; defekte Speicherzellen führen ohne übergeordnete NvM-Redundanzmechanismen (<em>Redundant Blocks</em>) zum Datenverlust.</li>\n</ul>"}], "trans": [{"from": "FIG-75959d56696099e2", "to": "FIG-38c6593ead6e4669", "fr": "R4.0.3", "tr": "R4.1.3", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\">\n<li>Bildausschnitt / Kopfbereich: Oberhalb des Diagrammrahmens wurde eine Textzeile aus dem vorausgehenden Spezifikationstext („number thus would be 17.“) in das Bild übernommen.</li>\n</ul>"}, {"from": "FIG-38c6593ead6e4669", "to": "FIG-6f36a54eb3458c11", "fr": "R4.1.3", "tr": "R4.2.2", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-6f36a54eb3458c11", "to": "FIG-145c8b4514ffef45", "fr": "R18-10_R4.4.0_R1.5.0", "tr": "R19-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-145c8b4514ffef45", "to": "FIG-ac637fea65c6a128", "fr": "R19-11", "tr": "R20-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-ac637fea65c6a128", "to": "FIG-ec6d8834130d7dfa", "fr": "R22-11", "tr": "R23-11", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\">\n<li>Füllmuster ungenutzter Speicherbereiche: Die Schraffur (graue Diagonallinien) in den ungenutzten Bereichen des virtuellen Adressraums (Block 1, Block 2, Block 3) sowie des physischen Adressraums wurde durch eine flächige hellgraue Füllung ersetzt.</li>\n<li>Begrenzungsrahmen: Der äußere schwarze Rahmen um das gesamte Diagramm wurde entfernt.</li>\n<li>Bildausschnitt: Die zuvor oberhalb des Rahmens sichtbare Textzeile („number thus would be 17.“) wurde entfernt; am unteren Rand sind Fragmente der Bildunterschrift sowie des nachfolgenden Textes sichtbar.</li>\n</ul>"}]};
